CREATE SET TABLE MDP01_META.META_DATA_QUALITY_RULE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      rule_id INTEGER NOT NULL,      rule_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      rule_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      table_id INTEGER,      column_id INTEGER,      rule_expression VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      rule_severity VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC,      beschreibung VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      beispiel_violation VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      is_active CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( rule_id )UNIQUE INDEX ( rule_name );